import { execFileSync } from 'node:child_process';
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const paths = execFileSync('npm', ['ls', '--omit=dev', '--all', '--parseable'], {
  encoding: 'utf8',
})
  .trim()
  .split('\n')
  .slice(1);
let text =
  '# Third-party notices\n\nGenerated by `node scripts/notices.mjs` from the locked production dependency tree.\nThe application bundles React, React DOM, React Router, AJV and AJV Formats. MSW and its dependencies load only in explicit mock mode.\n\n';
for (const dir of [...new Set(paths)].sort()) {
  const p = JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8'));
  const names = readdirSync(dir).filter((n) => /^(licen[cs]e|copying|notice)(\.|$)/i.test(n));
  text += `## ${p.name} ${p.version}\n\nLicense: ${p.license || 'See package license'}\n\n`;
  for (const name of names) {
    try {
      text +=
        '```text\n' +
        readFileSync(join(dir, name), 'utf8')
          .replace(/\r\n/g, '\n')
          .split('\n')
          .map((line) => line.trimEnd())
          .join('\n')
          .trim() +
        '\n```\n\n';
    } catch {}
  }
}
writeFileSync('THIRD_PARTY_NOTICES', text.trimEnd() + '\n');
